    summary: "水稻是亚洲最重要的粮食作物之一，籽粒脱壳后就是大米，养活了世界一半以上的人口，栽培历史逾万年。",
    description: "水稻是一年生草本植物，株高 0.6–1.5 m，根系为须根系，茎秆中空有节。叶片带状披针形，叶鞘抱茎，叶舌明显。稻穗为圆锥花序，小穗含一朵可育小花，自花授粉，成熟时籽粒呈淡黄或褐色，去壳后即糙米，再碾磨成白米。根据栽培环境可分为水稻和旱稻，按生育期分为早稻、中稻和晚稻。\n\n水稻原产中国长江流域与南亚一带，考古证据显示中国在约 1 万年前已开始驯化野生稻；如今从亚洲季风区到非洲、美洲的灌区都有种植。它喜高温多湿，需充足水分与肥沃土壤，多在水田中栽培。全球约一半人口以稻米为主食，中国是最大生产国之一。除食用外，稻草可作饲料、编织和还田，稻壳可发电、制板，是综合利用价值很高的作物。",
    habitat: "热带、亚热带水田与湿润平原，喜高温多湿和充足光照",
