    summary: "小麦是世界上种植最广的粮食作物之一，籽粒磨成面粉可制馒头、面包和面条，是许多地区的重要主食。",
    description: "小麦是一二年生草本，株高 0.6–1.2 m，须根系，茎秆直立、中空有节。叶片披针形，叶鞘抱茎。穗状花序顶生，由许多小穗两侧排列而成，每小穗含数朵小花，自花授粉。成熟时麦穗下垂或直立，籽粒呈金黄或褐色，腹面有深沟。按播种期分为冬小麦和春小麦，按粒质分为硬质和软质小麦。\n\n小麦起源于西亚的“新月沃地”，约 1 万年前由野生二粒小麦和山羊草杂交驯化而来，随农耕文明扩散到欧亚各地，是面包文明的基石。它喜温凉、光照充足的气候，冬小麦需经过低温春化才能抽穗结实。面粉中的面筋由麦谷蛋白和醇溶蛋白构成，赋予面团弹性，可用于制作馒头、面包、面条和糕点；麦麸、麦秆可作饲料和造纸原料。",
