    summary: "大豆富含蛋白质和油脂，可制成豆浆、豆腐、酱油和食用油，其根瘤还能固氮养地，是重要的经济作物。",
    description: "大豆是一年生草本，株高 0.5–1.5 m，全株密生褐色或灰色茸毛。叶为三出复叶，小叶宽卵形，边缘全缘。花小，蝶形，白色或淡紫色，自花授粉。荚果扁平，密被茸毛，内含 2–5 粒种子，种子圆球形，颜色有黄、青、黑、褐等，种脐明显。根系上着生许多根瘤，里面有共生的根瘤菌，能固定空气中的氮。\n\n大豆原产中国，栽培历史已有数千年，古代称“菽”，是五谷之一；19 世纪传入欧美后成为世界性作物。它喜温暖、光照充足，适宜在排水良好的壤土中生长。大豆种子含蛋白质约 35%–40%、脂肪约 18%–20%，是植物蛋白和食用油的重要来源，可加工成豆浆、豆腐、豆酱、酱油、豆油等；豆粕是优质饲料。根瘤菌固氮还能提高土壤肥力，因此常与玉米等轮作。",
