    description: "马铃薯是茄科一年生草本，株高 0.4–1 m，地上茎直立或半蔓生，羽状复叶，小叶卵形，全株有细毛。地下茎的末端膨大形成块茎，即我们食用的“土豆”，块茎表面有芽眼，颜色多为黄、白或紫红。花为聚伞花序，白、淡紫或蓝紫色，五裂，花药靠合。浆果球形，内含许多种子，但生产上多用块茎无性繁殖。\n\n马铃薯原产南美洲安第斯山区，约 7000–8000 年前由当地原住民驯化，16 世纪随西班牙人传入欧洲，后成为世界性的重要粮食作物，在爱尔兰历史上曾因晚疫病引发大饥荒。它喜冷凉湿润气候，适宜在疏松、排水良好的沙壤土中生长，多用块茎切块播种。块茎含淀粉约 12%–20%，可蒸煮、油炸，也可加工淀粉和酒精；但发芽的块茎和变绿部分含龙葵素，有毒不可食用。",
