    summary: "番茄的浆果酸甜多汁，富含番茄红素与维生素 C，可鲜食也可加工成酱，是世界上消费量最大的蔬菜之一。",
    description: "番茄是茄科一年生草本，株高 0.6–2 m，茎半直立或蔓生，表面有细柔毛和腺毛，揉搓后有特殊气味。叶为羽状复叶，小叶不规则，边缘有锯齿。花黄色，聚伞花序，自花授粉。果实为浆果，形状有圆、椭圆、长形等，成熟时呈红、粉、黄或橙色，果肉多汁，内含扁平种子，表面有绒毛。\n\n番茄原产南美洲安第斯山区，最初被欧洲人当作观赏植物，因被认为有毒而长期不食用，直到 18–19 世纪才逐渐走上餐桌。它喜温暖、光照充足，怕霜冻，适宜在肥沃、排水良好的土壤中栽培，可露地或温室种植。果实富含番茄红素、维生素 C 和有机酸，鲜食可做沙拉，也可加工成番茄酱、罐头和果汁；未成熟的青果含龙葵素，不宜食用。",
