    summary: "茶树的嫩叶经加工可制成绿茶、红茶等，是世界三大无酒精饮料之一，中国是最早种茶和饮茶的国家。",
    description: "茶树是山茶科常绿灌木或小乔木，株高 1–6 m，栽培茶树常修剪成 1 m 左右的灌丛。叶革质，椭圆或披针形，边缘有细锯齿，叶脉明显，嫩叶背面有白色茸毛。花白色，五瓣，雄蕊多数，有淡淡香气，花期 10–12 月。果实为蒴果，内含 1–3 粒种子。茶树的芽和嫩叶是制茶原料，按采摘标准和加工工艺不同，可制成绿茶、红茶、乌龙茶、白茶、黑茶等。\n\n茶树原产中国西南地区，云南、贵州、四川一带至今仍有野生古茶树；中国人发现和利用茶已有数千年，唐代陆羽著《茶经》系统总结种茶与饮茶之法，茶马古道把茶叶运往边疆与海外。茶树喜温暖湿润、酸性土壤和散射光，多分布在海拔 500–2000 m 的山地。茶叶含茶多酚、咖啡碱和氨基酸，饮茶提神解腻；茶多酚可提取作抗氧化剂。中国、印度、肯尼亚、斯里兰卡是主要产茶国。",
