    summary: "咖啡的种子烘焙磨粉后可冲泡成香浓饮品，阿拉伯咖啡风味柔和，是世界贸易量最大的农产品之一，也是重要的经济作物。",
    description: "咖啡是茜草科常绿灌木或小乔木，株高 3–5 m，野生可更高，栽培时多修剪至 2–3 m。叶对生，革质，椭圆形，深绿色，有光泽。花白色，五瓣，香气浓郁，多簇生于叶腋，花期集中。果实为浆果，未熟时绿色，成熟后呈深红色，形似樱桃，内含两粒扁平的种子，即咖啡豆。种子经脱皮、发酵、干燥和烘焙后，才能散发出浓郁的香气。\n\n阿拉伯咖啡原产埃塞俄比亚高原，传说当地牧羊人发现羊吃咖啡果后精神亢奋，此后咖啡逐渐被人类利用；15 世纪经也门传入阿拉伯半岛，再传播到欧洲和美洲。它喜温暖、湿润、半阴的环境，适宜在海拔 1000–2000 m 的山地栽培，耐寒性较差，易受叶锈病影响，目前以杂交和抗病品种改良为主。咖啡豆富含咖啡因，可提神醒脑；全球咖啡种植支撑着许多热带国家的经济。",
