    description: "可可是锦葵科常绿小乔木，株高 4–8 m，树皮灰褐色，叶片大而革质，卵状椭圆形，互生，长可达 30 cm。花小而精致，淡黄或粉白色，直接开在树干和老枝上，这种现象称为“老茎生花”。果实为荚果，长椭圆形，表面有纵沟，成熟时呈橙黄或紫红色，内含 20–50 粒扁椭圆形的种子，即可可豆，种子外裹白色果肉。\n\n可可原产南美洲亚马孙河流域，玛雅和阿兹特克文明早在数千年前就用可可豆制作带苦味的饮料，可可豆甚至被当作货币；16 世纪传入欧洲后，加入糖和牛奶逐渐演变成巧克力。可可喜高温高湿、遮阴环境，多栽培于赤道附近的热带雨林地区，常与其他高大树种间作。可可豆经发酵、日晒、烘焙和研磨后制成可可粉与巧克力，其含有的可可碱和咖啡因有提神作用，西非的科特迪瓦、加纳是主要生产国。",
