    description: "甘蔗是禾本科多年生高大草本，株高 2–4 m，茎秆粗壮、实心，有节，节上着生芽，表面常被白色蜡粉，颜色有绿、黄、紫红等。叶片长披针形，边缘有锋利的锯齿，需小心触碰。茎秆内富含汁液，含糖量可达 12%–16%。甘蔗很少开花，开花时会抽出顶生的圆锥花序。生产上通常用茎段（种苗）无性繁殖，每段保留 2–3 个芽。\n\n甘蔗原产新几内亚与南亚一带，约 8000 年前已被当地人栽培，后经印度传入中国，成为重要的制糖原料，古代蔗糖曾是中国出口的大宗商品。它喜高温、强光和充足水分，适宜在热带、亚热带地区栽培。甘蔗压榨出的汁液可熬制成蔗糖，副产品糖蜜可发酵生产酒精，蔗渣可造纸、发电和作饲料；甘蔗乙醇也是重要的生物燃料。巴西、印度和中国是主要生产国。",
