    description: "棉花（陆地棉）是锦葵科一年生亚灌木状草本，株高 1–1.5 m，茎直立，有茸毛或光滑。叶片宽卵形，掌状 3–5 裂，边缘有锯齿。花大而美，初开为乳白色，后渐变为淡黄或粉红，花瓣五片，基部有红色斑点。果实为蒴果，称为棉铃，成熟后裂开，露出四团白色棉絮，每个棉铃内有 8–10 粒种子，种子上着生纤维。\n\n棉花原产美洲热带与亚热带地区，人工栽培历史超过 5000 年，19 世纪随纺织工业兴起成为全球性商品，美国南部、印度、中国、巴西等地都是主产区。棉花喜温暖、光照充足，生长期需水量较大但不耐涝，适宜在土层深厚的壤土中栽培。棉纤维可纺纱织布，棉籽可榨油、作饲料，棉籽壳可种菇；棉籽中含棉酚，需脱毒后利用。中国的新疆棉区以优质长绒棉闻名。",
