    description: "油菜（甘蓝型油菜）是十字花科一二年生草本，株高 0.5–1.5 m，茎直立，多分枝。叶片互生，基生叶有柄，茎生叶基部抱茎，表面有蜡粉。花为总状花序，金黄色，四瓣十字形，雄蕊六枚，四强雄蕊。果实为长角果，成熟后开裂，内含 10–20 粒球形种子，颜色呈黑、褐或黄，含油量约 40%。\n\n油菜起源于欧洲地中海地区与亚洲，由甘蓝与芜菁杂交演化而来，中国是世界上最大的油菜生产国之一，长江流域冬油菜种植广泛。它喜凉爽湿润、光照充足，耐寒性较强，常以水稻与油菜轮作的方式种植。油菜籽可榨取菜籽油，菜籽饼是优质饲料和肥料；油菜花在春季形成大片金黄色花海，带动乡村旅游。双低油菜（低芥酸、低硫苷）品种的推广，使菜籽油的营养价值明显提高。",
