    description: "毛竹是禾本科刚竹属的大型常绿竹类，秆高可达 10–20 m，直径 8–20 cm，节间长，秆环不明显，新竹表面有细柔毛和白粉，老秆转为黄绿色。叶片披针形，较小。毛竹靠地下横走的竹鞭繁殖，竹鞭上的芽可长出竹笋，春季竹笋破土后生长极快，某些条件下一天可长高数十厘米。开花周期很长，开花后往往整片竹林枯死。\n\n毛竹原产中国，是中国分布最广、栽培面积最大的竹种之一，长江以南的浙江、福建、江西、湖南等地有大片毛竹林。它喜温暖湿润、土层深厚的酸性土壤，生长迅速，成林快。毛竹笋可鲜食或制成笋干、罐头；竹材韧性好，可用于建筑脚手架、竹地板、家具、竹编和造纸；竹叶可制茶。毛竹固碳能力强，是重要的生态与经济兼用竹种，但竹林若长期不采伐会退化。",
