    description: "橡胶树是大戟科落叶乔木，高可达 20–30 m，树皮灰褐色，较平滑，割开后可见乳白色的胶乳。叶为三出复叶，小叶椭圆或倒卵形，全缘，叶柄顶端有腺体。花小，单性同株，圆锥花序，无花瓣。果实为蒴果，球形，成熟后裂开，内含 3 粒种子，种子有斑纹。树皮中的乳管系统是胶乳产生和储存的部位。\n\n橡胶树原产南美洲亚马孙河流域，当地原住民早已使用橡胶制作球和防水布；19 世纪种子被引种到东南亚，如今泰国、印度尼西亚、马来西亚等国成为主要产胶区，中国云南、海南也有大面积种植。它喜高温、高湿和充足光照，适宜在赤道附近低海拔地区栽培。割胶时在树干上割开螺旋形切口，胶乳沿切口流入收集杯，经凝固、压片、干燥后制成天然橡胶，用于轮胎、胶管、手套等。",
