    description: "燕麦是一年生草本，株高 0.6–1.5 m，须根系，茎秆直立。叶片扁平，较宽。圆锥花序顶生，分枝下垂，小穗含 2–3 朵小花，多自花授粉，成熟时小穗下垂如铃铛，种子外被稃壳。按栽培方式分为皮燕麦和裸燕麦，裸燕麦即莜麦，籽粒可直接磨粉食用。\n\n燕麦原产欧洲与西亚一带，栽培历史约 2000–3000 年，由野燕麦驯化而来，是温带冷凉地区的重要谷物。它喜凉爽湿润气候，耐寒、耐瘠薄，对土壤要求不严，但忌高温干旱。燕麦籽粒富含膳食纤维，尤其是 β-葡聚糖，可加工成燕麦片、燕麦粉，是公认的健康食品；茎叶柔嫩多汁，是优良的饲草。中国内蒙古、河北、山西等地是裸燕麦（莜麦）的主产区。",
