    description: "高粱是一年生高大草本，株高 1–3 m，茎秆粗壮、实心，叶片宽大。圆锥花序顶生，穗形因品种而异，有紧穗、散穗之分，籽粒球形，颜色有红、白、黄、褐等，常外露或包于颖壳中。高粱的根系发达，茎秆表面有蜡粉，能减少水分蒸发。\n\n高粱原产非洲，约 4000 年前被驯化，后经印度传入中国，是中国北方重要的旱地粮食作物。它耐旱、耐涝、耐盐碱，适应性极强，在干旱半干旱地区也能获得较好收成。高粱籽粒可煮食、磨粉，也是酿造白酒、食醋的重要原料，中国许多名酒都以高粱为主要原料；茎秆可作燃料、编织材料和饲料，穗可制扫帚。近年来，高粱还因耐旱节水被用于干旱地区的生态种植。",
