    description: "谷子是一年生草本，株高 0.6–1.5 m，茎秆直立，叶片披针形。圆锥花序顶生，穗形有纺锤形、圆筒形、棍棒形等，成熟时下垂，籽粒小，球形，颜色有黄、白、红、黑等，脱壳后即小米。谷子的根系发达，耐旱性强，是典型的旱地作物。\n\n谷子原产中国黄河流域，考古证据显示中国在约 8000 年前已开始驯化谷子，是世界上最古老的栽培作物之一。它耐旱、耐瘠薄、生育期短，适合在干旱半干旱地区种植，曾长期是中国北方的主粮。小米富含蛋白质、维生素 B 族和矿物质，可煮粥、蒸饭、磨粉，是产妇与体弱者的滋补食品；谷草是优质饲料，谷糠可作饲料与酿酒辅料。如今谷子更多作为杂粮和特色作物种植。",
