    description: "荞麦是一年生草本，株高 0.4–1 m，茎直立，多分枝，呈红绿色。叶片心形或三角形，互生，托叶鞘状。花白色或淡红色，花瓣五枚，总状花序，花蜜丰富。果实为瘦果，三棱形，成熟时黑褐色或棕褐色，种子富含淀粉。荞麦不是禾本科的“麦”，而是蓼科植物，形态与麦类差别很大。\n\n荞麦原产中国东北与西伯利亚一带，栽培历史约 2000–3000 年，是重要的杂粮与救荒作物。它生育期短，仅 60–90 天，耐瘠薄、适应性强，可作灾后补种作物；花果期长，是优良的蜜源植物。荞麦籽粒可磨粉制成饸饹、面条、饼类，富含蛋白质、膳食纤维和芦丁等黄酮类物质；荞麦茎叶柔嫩，可作饲料或绿肥。中国北方与西南山区是荞麦主产区，苦荞是荞麦的一个近缘种，营养价值很高。",
