    description: "甘薯是旋花科一年生或多年生草本，茎蔓生，匍匐地面，长可达 2–3 m，节上易生不定根。叶片心形或掌状分裂，互生。花漏斗状，淡紫色或白色，少见开花。地下不定根膨大形成块根，形状有纺锤形、球形等，皮色有红、黄、白、紫等，肉色也因品种而异。\n\n甘薯原产南美洲热带地区，约 5000 年前被驯化，16 世纪经海路传入中国，因耐旱耐瘠、产量高而迅速推广。它喜温暖、光照充足，耐干旱、耐瘠薄，不耐霜冻，适宜在土层深厚的沙壤土中种植，多用块根育苗扦插繁殖。块根富含淀粉、糖分和胡萝卜素，可蒸煮、烤食、煮粥，也可加工淀粉、粉丝、粉条和酒精；茎叶嫩梢可作蔬菜，藤蔓可作饲料。中国是世界上最大的甘薯生产国。",
