    description: "山药是薯蓣科多年生缠绕草本，茎细长，右旋缠绕，可长达数米，常带紫色。叶片三角形或卵形，对生或互生，叶腋常生珠芽（零余子）。地下块茎圆柱形、棒状或掌状，外皮灰褐色，表面密生须根，肉质洁白，富含黏液。雌雄异株，穗状花序，花小，黄绿色。\n\n山药原产中国，栽培历史已有 2000 多年，是重要的药食两用作物，河南焦作一带的“怀山药”最为著名。它喜温暖、光照充足，耐旱怕涝，适宜在土层深厚、排水良好的沙壤土中种植，多用块茎切段或珠芽繁殖。块茎富含淀粉、黏液质和多种氨基酸，可炖汤、清炒、蒸食，是常见的食材；中医认为山药有补脾肺、益肾气之效，是传统滋补药材。山药的地下块茎入土较深，采收需深挖。",
