    description: "芋头是天南星科多年生草本，株高 0.8–1.5 m。叶片大，盾状心形或箭形，长 20–60 cm，叶柄长而肥厚，呈绿色或紫红色。地下球茎（母芋）球形或椭圆形，周围着生许多小芋（子芋），球茎富含淀粉，表面有褐色纤维状鳞叶。肉穗花序藏在叶鞘内，佛焰苞黄色。\n\n芋头原产南亚与东南亚的热带地区，栽培历史数千年，中国南方栽培普遍，是重要的粮菜兼用作物。它喜高温高湿、半阴环境，不耐寒，适宜在土层深厚、保水力强的壤土中种植，多用子芋繁殖。芋头球茎富含淀粉和黏液，可蒸煮、炖肉、做甜品，是南方节庆与日常食材；叶柄可腌制食用。芋头的黏液含草酸钙针晶，生芋接触皮肤会发痒，需煮熟后食用。",
    habitat: "热带、亚热带湿润的平原与山麓，喜高温高湿、半阴",
    distribution: "原产南亚与东南亚，现中国南方、东南亚、太平洋岛屿等地广泛栽培",
