    description: "木薯是大戟科灌木状多年生植物，株高 1–3 m，茎直立、木质化，有节。叶片掌状深裂，裂片 3–7 枚，盾形，叶柄长。花单性同株，圆锥花序，花小，黄白色。地下块根圆柱形或纺锤形，长 30–100 cm，富含淀粉，外皮褐色，肉白色。\n\n木薯原产南美洲亚马孙流域，当地原住民栽培历史已有数千年，19 世纪传入非洲和亚洲，如今是热带地区重要的粮食和淀粉作物。它耐旱、耐瘠薄，适应酸性土壤，管理粗放，产量高。块根含淀粉约 20%–30%，可加工成木薯粉、木薯淀粉、珍珠奶茶中的“珍珠”和酒精、饲料；但生木薯含氰苷，有毒性，必须经浸泡、煮熟或发酵脱毒后才能食用。中国广东、广西、海南等地有种植。",
