    taxonomy: { phylum: "被子植物门", class: "双子叶植物纲", order: "石竹目", family: "藜科", genus: "甜菜属" },
    summary: "甜菜是仅次于甘蔗的制糖原料，块根含糖量高，可提制白糖，叶可作蔬菜和饲料，是温带重要的经济作物。",
    description: "甜菜是藜科二年生草本，第一年形成肥大的块根，第二年抽薹开花。叶片卵形或长圆形，叶柄长而肉质，叶面有皱褶，呈深绿色或紫红色。块根形状有圆锥形、纺锤形等，皮色有白、黄、红等，肉质白色，富含糖分。花小，绿色，圆锥花序，种子为聚花果。\n\n甜菜原产地中海沿岸与西亚，栽培历史约 4000 年，最初作蔬菜和饲料，18 世纪欧洲培育出糖用甜菜，开始大规模制糖。它喜凉爽湿润气候，耐寒、耐盐碱，适宜在温带肥沃的壤土中种植。糖用甜菜块根含糖约 15%–20%，是制糖工业的重要原料，与甘蔗并称两大糖源；叶片和根渣可作饲料。中国东北、西北与内蒙古是甜菜主产区。叶用甜菜（牛皮菜）与根用甜菜（红甜菜）也是常见蔬菜。",
