    description: "芝麻是一年生草本，株高 0.6–1.5 m，茎直立，四棱形，有分枝，全株有短柔毛。叶片互生或对生，卵形或披针形。花白色或淡紫色，筒状唇形，单生或簇生于叶腋。蒴果四棱形，成熟时开裂，内含许多扁椭圆形种子，颜色有白、黑、黄、褐等。\n\n芝麻原产非洲或印度一带，栽培历史已有 5000 多年，后传入中国，古代称“胡麻”，是重要的油料作物。它喜温暖、光照充足，不耐霜冻，适宜在排水良好的壤土中种植。芝麻种子含油约 45%–55%，可榨取芝麻油（香油），香味浓郁，是烹饪与调味的上品；种子可制芝麻酱、芝麻糖、糕点和芝麻糊。芝麻富含维生素 E 和钙，黑芝麻在中医里被认为有补肝肾、润肠燥之效。中国河南、湖北、安徽是主产区。",
