    summary: "蓖麻的种子富含蓖麻油，是重要的工业油料，可用于航空、机械和医药，但种子含蓖麻毒素，严禁食用。",
    description: "蓖麻是大戟科一年生或多年生草本或小乔木，热带可长成 5 m 高的小树。叶片大，掌状深裂，裂片 7–11 枚，边缘有锯齿，叶柄长，盾状着生。花单性同株，圆锥花序，上部为雌花、下部为雄花。蒴果球形，表面有软刺，成熟时开裂，内含 3 粒种子，种子椭圆形、有花纹。\n\n蓖麻原产非洲东北部与中东一带，栽培历史数千年，如今在热带、亚热带广泛种植。它适应性强，耐旱、耐瘠薄，对土壤要求不严。蓖麻种子含油约 50%，蓖麻油黏度高、耐高温，是优良的工业润滑油，可用于航空发动机、机械与橡胶工业，也可用于医药和化妆品。蓖麻种子含有蓖麻毒素，毒性极强，误食会危及生命，必须严防误食，榨油后的饼粕需脱毒处理才能作饲料或肥料。",
