    summary: "亚麻的茎皮纤维可织成亚麻布，种子可榨油，是重要的纤维与油料两用作物，栽培历史已有五千多年。",
    description: "亚麻是一年生草本，株高 0.5–1.2 m，茎直立、细长，上部有分枝。叶片披针形或线形，互生。花蓝色或白色，五瓣，生于枝顶，清晨开放。蒴果球形，内含 10 粒扁卵形种子，种子黄褐色或棕色，富含油脂。按用途分为纤维用亚麻、油用亚麻和兼用亚麻。\n\n亚麻原产中亚与地中海一带，栽培历史已有 5000 多年，是古老的纤维与油料作物。纤维用亚麻茎秆细长，茎皮纤维坚韧、吸湿透气，可织成亚麻布、帆布和窗帘；油用亚麻（胡麻）种子含油约 35%–45%，可榨取亚麻籽油，富含 α-亚麻酸，是重要的保健食用油，也可用于油漆和油墨工业。中国东北是纤维用亚麻的主产区，西北与华北则多油用亚麻。亚麻籽还可作饲料。",
