    summary: "桑树的叶片是家蚕的主要饲料，果实桑葚可食，皮可造纸，是蚕桑业的基础树种，栽培历史逾五千年。",
    description: "桑树是桑科落叶乔木或灌木，高可达 10 m，树皮灰褐色、纵裂。叶片卵形或宽卵形，边缘有粗锯齿，有时分裂，表面无毛、背面脉腋有毛，叶柄长。花单性，雌雄异株或同株，柔荑花序。果实为聚花果，即桑葚，长圆形，成熟时紫黑色、红色或白色，酸甜多汁。\n\n桑树原产中国，栽培历史已有 5000 多年，是蚕桑业的物质基础，也是重要的经济树种。它喜温暖、光照充足，耐旱、耐寒、耐修剪，适应性强，对土壤要求不严。桑叶是家蚕的主要饲料，养蚕缫丝造就了丝绸之路；桑葚可鲜食、制干、酿酒，富含维生素和花青素；桑树皮纤维可造纸，桑枝可作菌菇培养料，根皮、叶、果均可入药。中国是世界上最大的蚕丝生产国，桑树在南方蚕区广泛种植。",
    habitat: "温带与亚热带的山坡、田边与庭院，适应性极强",
    distribution: "原产中国，现广泛栽培于中国、印度、日本及东南亚等地",
