    summary: "啤酒花的雌花含蛇麻酮和挥发油，能赋予啤酒独特的苦味与香气，并延长保质期，是酿造啤酒的关键原料。",
    description: "啤酒花是大麻科多年生缠绕草本，茎蔓生，长可达 6–8 m，有倒刺，可攀援生长。叶片对生，掌状 3–5 裂，边缘有锯齿，表面粗糙。雌雄异株：雄花为圆锥花序，雌花为球果状穗状花序，由许多苞片和雌花组成，俗称“酒花”。成熟时球果呈黄绿色，含有蛇麻酮和挥发油。\n\n啤酒花原产欧洲、西亚与北美一带，人工栽培历史约 1000 年，是酿造啤酒的关键原料。它喜凉爽湿润、光照充足，适宜在土层深厚、排水良好的土壤中种植，用地下茎扦插繁殖，地上部每年冬季枯萎。雌花球果中的蛇麻酮提供啤酒的苦味，挥发油带来花香与果香，还有防腐作用、延长啤酒保质期。啤酒花也可用于制药，有镇静、助消化之效。中国新疆、甘肃是主产区，近年来精酿啤酒兴起使啤酒花需求增加。",
    habitat: "温带凉爽地区的平原与山地，喜凉爽湿润、光照充足",
    distribution: "原产欧洲、西亚与北美，现主产于德国、美国、中国新疆与甘肃",
    conservation: "暂无评估（栽培作物）",
