    description: "姜是姜科多年生草本，株高 0.5–1 m，根状茎肉质、肥厚，呈不规则块状，表面淡黄色，有芳香辛辣味。叶片披针形，二列互生，叶鞘抱茎。花通常不开，穗状花序由根状茎抽出，苞片绿色或紫红色，花冠黄绿色。生产上多用根状茎（姜块）无性繁殖。\n\n姜原产东南亚热带地区，中国栽培历史已有 2000 多年，是重要的调味与药用作物。它喜温暖湿润、半阴环境，不耐霜冻，适宜在疏松肥沃的沙壤土中种植，用姜块催芽后播种。嫩姜可腌制、炒食，老姜辛辣味浓，是烹饪去腥增香的主要调料；姜还可加工成姜粉、姜油、姜糖和姜茶。中医认为生姜有发汗解表、温中止呕之效。中国山东、河南、四川、贵州等地是主产区。",
