    description: "洋葱是石蒜科一二年生草本，株高 0.6–1 m。叶片圆筒形、中空，表面有蜡粉，叶鞘抱合形成假茎。地下鳞茎球形或扁球形，由多层肥厚的鳞片抱合而成，外皮有紫红、黄白等色。伞形花序顶生，花小、白色，但栽培上多用种子繁殖。\n\n洋葱原产中亚与西亚一带，栽培历史已有 5000 多年，是世界上最古老、种植最广的蔬菜之一。它喜凉爽、光照充足，适宜在疏松肥沃、排水良好的土壤中种植，鳞茎膨大期需要较长光照和较高温度。洋葱的鳞茎富含糖分、维生素和含硫化合物，切开会释放丙硫醛 S-氧化物，刺激眼睛流泪；可鲜食、炒食、做汤或加工成洋葱粉、洋葱油。洋葱耐储运，是重要的出口蔬菜。中国是世界上最大的洋葱生产国之一。",
