    description: "萝卜是十字花科一二年生草本，株高 0.3–0.6 m。基生叶羽状分裂，边缘有锯齿，表面粗糙。肉质根形状有长圆柱形、球形、圆锥形等，皮色有白、红、青、紫等，肉色多为白色，脆嫩多汁，富含水分和维生素 C。花为总状花序，白色或淡紫色，四瓣十字形。\n\n萝卜原产中国与地中海一带，中国栽培历史已有 2000 多年，是重要的根菜作物。它喜凉爽、光照充足，适宜在疏松深厚的沙壤土中种植，肉质根膨大期怕高温和干旱。萝卜可生食、炒食、炖汤、腌制，萝卜缨（叶）也可作蔬菜或饲料；种子（莱菔子）入药，有消食化积、降气化痰之效。萝卜富含维生素 C、膳食纤维和芥子油，生食有辛辣味。中国各地均有栽培，品种极为丰富。",
