    description: "茄子是一年生或多年生草本，株高 0.6–1.5 m，茎直立，有分枝，全株有星状柔毛，常带紫色。叶片卵形或长圆状卵形，边缘有浅裂。花单生或簇生，花冠紫色或白色，五裂。果实为浆果，形状有长条形、圆形、卵形等，皮色有紫、红紫、白、绿等，果肉白色，含浆果状种子。\n\n茄子原产印度与东南亚热带地区，栽培历史已有 2000 多年，汉代传入中国。它喜温暖、光照充足，生长期较长，不耐霜冻，适宜在疏松肥沃、排水良好的土壤中种植。茄子果实可炒食、蒸食、红烧、凉拌和腌制，是夏季主要蔬菜之一；富含膳食纤维、维生素 P（芦丁）和花青素，紫色的果皮中花青素含量较高。茄子叶和根在民间也作药用。中国是世界上最大的茄子生产国之一。",
