    summary: "藜麦的种子富含优质蛋白和氨基酸，被联合国粮农组织推荐为营养食品，原产安第斯山区，是伪谷物作物。",
    description: "藜麦是一年生草本，株高 1–2 m，茎直立，有分枝。叶片互生，三角形或掌状分裂，边缘有齿，表面有粉霜。花小，黄绿色，圆锥花序，密集着生在枝顶。种子扁圆形，直径 1–2 mm，颜色有白、红、黑等，外有一层含皂苷的种皮。藜麦不是禾草，而是藜科植物，属于“伪谷物”。\n\n藜麦原产南美洲安第斯山区，是当地原住民的传统粮食，栽培历史数千年。它耐旱、耐寒、耐盐碱，适应性强，适宜在高原冷凉地区种植。种子富含蛋白质、必需氨基酸、膳食纤维和矿物质，营养价值高，被联合国粮农组织推荐为营养食品，近年来在国际市场广受欢迎。食用前需用水搓洗去除种皮中的皂苷，否则会有苦味；可煮饭、煮粥、做沙拉。中国青海、甘肃等地已引种栽培。",
