    description: "籽粒苋是一年生草本，株高 1–2.5 m，茎直立、粗壮，有分枝。叶片宽卵形或披针形，互生。花小、密集，圆锥花序顶生，呈穗状，颜色有红、绿、黄等，种子极小，圆球形，颜色有白、黄、黑等。它生长迅速，生物量大。\n\n籽粒苋原产中美洲与南美洲，是古美洲原住民的粮食作物之一，后引种到世界各地。它喜温暖、光照充足，耐旱、耐瘠薄，适应性极强，适宜在瘠薄旱地种植。种子富含蛋白质、赖氨酸和钙，可煮粥、磨粉、做膨化食品；嫩叶可作蔬菜，茎叶是优质饲料，也可作绿肥。籽粒苋生长快、产量高，在旱作农业和饲草生产中很有潜力。中国北方与西南有栽培。",
