    description: "茼蒿是一年生或二年生草本，株高 0.2–0.5 m。茎直立，肉质。叶片互生，羽状深裂，裂片狭长，肉质柔嫩，有特殊的清香气味。花为头状花序，黄色或白色，但栽培上以采嫩茎叶为主，抽薹开花后品质下降。\n\n茼蒿原产地中海沿岸，中国栽培历史悠久，是秋冬季的常见蔬菜。它喜冷凉湿润、光照充足，不耐高温，适宜在疏松肥沃、保水力强的土壤中种植，生育期短，可分批播种。嫩茎叶可炒食、凉拌、涮火锅、做汤，有独特的清香，口感柔嫩。茼蒿富含维生素、胡萝卜素和膳食纤维，是低热量蔬菜。栽培时注意保持土壤湿润，避免高温抽薹。",
