    description: "芦笋是天门冬科多年生草本，株高 1–2 m，地下有肉质根状茎和须根。茎直立，多分枝；叶片退化成鳞片状，光合作用由绿色针状的“叶状枝”完成。嫩茎从地下抽出，可食用；成熟植株开黄绿色小花，结红色浆果。雌雄异株。\n\n芦笋原产地中海沿岸与西亚，栽培历史已有 2000 多年，如今世界各地广泛种植，中国是主要生产国之一。它喜温暖湿润、光照充足，适宜在疏松深厚、排水良好的沙壤土中种植，一次栽种可连续采收 10–15 年。嫩茎可鲜食、焯水凉拌、炒食、做汤，也可加工成罐头。芦笋富含天门冬酰胺、膳食纤维和叶酸，是公认的高档保健蔬菜。栽培中需注意防治茎枯病。",
