    description: "木耳菜是落葵科一年生或二年生缠绕草本，茎肉质、光滑，可攀援 2–3 m，节上易生不定根。叶片互生，卵形或心形，肉质肥厚，深绿色，有光泽；叶柄短。花小，白或紫红色，穗状花序。果实为浆果，成熟时紫黑色，内含一粒种子。\n\n木耳菜原产热带亚洲与非洲，中国南方栽培较为普遍。它喜温暖湿润、半阴环境，耐热、不耐寒，适宜在疏松肥沃、保水力强的土壤中种植，多搭架或任其攀爬。嫩茎叶可炒食、煮汤，口感滑嫩如木耳，因此得名；富含维生素、矿物质和黏液质。木耳菜生长快、采收期长，是南方夏季的重要绿叶蔬菜。栽培时注意保持土壤湿润，避免干旱。",
