    description: "牛蒡是菊科二年生草本，株高 1–2 m。第一年只长叶和肉质根，第二年抽薹开花。叶片大，心形或宽卵形，表面粗糙，背面有白色绒毛；根肉质、圆柱形，长可达 1 m，外皮灰褐色。花为头状花序，紫红色，总苞片呈钩状，能附着在动物身上传播种子。\n\n牛蒡原产欧洲与亚洲，中国栽培历史悠久，日本将其发展为重要蔬菜。它喜温暖湿润、光照充足，适宜在土层深厚、疏松的沙壤土中种植，深根性，要求土壤疏松以便肉质根伸长。肉质根可炖汤、炒食、凉拌、泡茶，有特殊的香气；富含膳食纤维、菊糖和矿物质。中医认为牛蒡有疏散风热、清热解毒之效。日本、中国台湾等地消费量大，中国江苏、山东等地有规模化种植。",
    habitat: "温暖湿润的沙壤土，土层需深厚疏松",
