    description: "魔芋是天南星科多年生草本，株高 0.5–1.5 m。地下球茎扁球形，富含葡甘聚糖；叶片大，掌状复叶，叶柄粗壮、有斑纹，每年只抽生一叶。花为肉穗花序，佛焰苞紫红色，花有臭味，靠苍蝇传粉。魔芋通常先长叶、后开花，开花后球茎养分耗尽。\n\n魔芋原产中国南方与东南亚，中国栽培历史悠久，云南、四川、湖北等地为主产区。它喜温暖湿润、半阴环境，不耐寒，适宜在土层深厚、排水良好的土壤中种植。球茎含葡甘聚糖，经加工可制成魔芋豆腐、魔芋粉丝、魔芋爽等食品，低热量、富含膳食纤维，有饱腹感；工业上还可用于造纸、印染和石油钻井。注意生魔芋块茎含草酸钙针晶和生物碱，有毒，必须经碱水煮制等加工后才能食用。",
