    description: "菊芋是菊科向日葵属的多年生草本，株高 1.5–3 m，茎直立粗壮、被短毛。叶片互生、卵形、边缘具锯齿，表面粗糙；秋季开黄色头状花序，形似小型向日葵。地下匍匐茎末端膨大成不规则块茎，皮色白、红或紫，肉白色，富含菊糖，因此又称洋姜。\n\n菊芋原产北美洲，17 世纪传入欧洲，后经海路进入中国，如今南北各地都有栽培或逸生。它耐寒、耐旱、耐瘠薄，对土壤要求不高，块茎在冻土中也能越冬。块茎可腌制、炒食、煮食或提取菊粉，菊粉是天然的益生元与低热量甜味剂；茎叶可作饲料，块茎也可发酵生产乙醇，被视为潜在的能源作物。栽培上以块茎繁殖为主，繁殖力极强，逸生后较难清除，种植时需注意控制范围。",
