    summary: "葛根是豆科藤本植物葛的块根，富含淀粉，可制葛粉、葛根粉条，也常用于煲汤，是中国南方常见的药食两用作物。",
    description: "葛是豆科多年生缠绕藤本，块根粗大，外皮黄褐色，内部白色，富含淀粉，垂直深入土中，可长达一米以上。茎长可达数米，密生黄色硬毛。三出复叶，小叶菱状卵形，全缘或浅裂，叶背有毛。总状花序腋生，花紫红色，荚果扁平，密被硬毛。\n\n葛原产中国、日本及东南亚，适应性强，常攀援于山坡、灌丛和林缘。它喜温暖湿润，耐旱耐瘠，根系发达，能固土护坡。块根在秋冬采收，洗净后磨浆沉淀可得葛粉，也可鲜食、炖汤或入药；葛花可解酒，藤蔓可作饲料和编织材料。中国南方山区常人工栽培，是兼具生态与经济效益的作物。葛根还常与排骨、鲫鱼同炖，汤味清甜，也可切片晒干保存。",
