    summary: "梨是蔷薇科落叶果树，果实脆嫩多汁、清甜爽口，可鲜食或熬制秋梨膏，中国是梨的主要原产地和栽培中心之一。",
    description: "梨是蔷薇科落叶乔木，株高可达 5–8 m，树皮灰褐色，小枝光滑，寿命较长，盛果期可达数十年。叶片卵形或椭圆形，边缘有细锯齿，秋季变为红黄色。伞房花序，花白色，先于叶或与叶同时开放。果实为梨果，近球形或倒卵形，果皮黄白或黄褐色，果肉白色，脆嫩多汁，果心内有数粒黑色种子。\n\n梨原产中国、欧洲和西亚，栽培历史至少三千年。中国是白梨、沙梨和秋子梨等重要种类的原产地，河北、山东、辽宁等地为主要产区，鸭梨、雪花梨、酥梨等品种各具风味。梨树喜光、耐寒，对土壤要求不严，但以深厚疏松的沙壤土为佳。花期需防霜冻，果实成熟后要适时采收。除鲜食外，梨还可加工罐头、梨膏、果酒；木材细致，可用于雕刻。",
