    description: "李是蔷薇科落叶小乔木，株高 3–6 m，树皮灰褐色，小枝红褐色，树冠开张。叶片椭圆或倒卵形，边缘有细锯齿。花白色，常三朵并生，先于叶开放，早春满树雪白。果实为核果，圆形或心形，果皮有黄、红、紫等色，表面常被果粉，果肉淡黄或红色，汁多味酸甜，核面有皱纹。\n\n李原产中国，栽培历史超过三千年，《诗经》中已有记载。中国李适应性广，从华北到西南均有栽培，日本、韩国和欧美也有引种。它喜光、耐寒耐旱，但花期怕霜冻，适宜在排水良好的沙壤土生长。果实不耐贮运，多就近鲜销或加工成蜜饯、果酱、果酒。李花洁白繁密，也是春季观花树种，按果皮颜色还可分为黄李、红李和紫李等。",
