    description: "樱桃是蔷薇科落叶乔木，株高 6–10 m，树皮红褐色，小枝光滑，树姿开张，幼树生长旺盛。叶片卵形或长圆状卵形，边缘有重锯齿，叶柄近顶端有腺体。伞形花序，花白色，略带香气。果实为核果，近球形，果皮鲜红至紫黑色，果肉淡黄或红色，柔软多汁，核圆形。\n\n甜樱桃原产欧洲东南部与西亚，19 世纪引入中国，如今山东、辽宁、河北等地栽培较多。它喜凉爽干燥、光照充足的气候，需冬季低温休眠，花期怕霜冻和阴雨，适宜在排水良好的沙壤土生长。甜樱桃自花结实率低，果园常配置授粉树。果实成熟期集中在初夏，不耐贮运，多鲜食，也可加工罐头、果酱和果酒。中国本土的中国樱桃栽培历史更久，但果小、皮薄。",
