    description: "柚子是芸香科常绿乔木，株高可达 5–10 m，枝条有刺，嫩枝被柔毛。叶片阔卵形或椭圆形，叶柄有倒心形宽翼。花白色，芳香。果实为柑果，大型，近球形或梨形，果皮厚，黄绿色或黄色，海绵层包裹着成簇的汁胞，果肉有白色、粉红或红色，汁胞细长，清甜多汁。\n\n柚子原产中国南部与东南亚，栽培历史悠久，中国是柚的重要原产地之一。它喜温暖湿润、光照充足，适宜在土层深厚、排水良好的地方生长。果实秋季成熟，耐贮藏，可存放数月。除鲜食外，柚皮可制蜜饯、柚皮糖，果肉可制果汁；柚木材质细密。广西沙田柚、福建琯溪蜜柚等都是著名品种。柚子在民间常象征团圆，是中秋应节水果。",
