    summary: "菠萝是凤梨科多年生草本，果实由许多小花聚合而成，酸甜多汁、香气浓郁，可鲜食或加工罐头、果汁，是热带名果。",
    description: "菠萝是凤梨科多年生草本，株高 0.5–1 m，叶片剑形，簇生，边缘有锯齿，叶面深绿，叶背灰绿。叶簇中央抽生花序，花序由许多小花组成，聚合成肉质的聚花果，果实顶端长有冠芽。果皮由许多六角形小果眼组成，成熟时黄绿或橙黄，果肉黄色，酸甜多汁。\n\n菠萝原产南美洲巴西、巴拉圭一带，印第安人早已栽培，15 世纪后随航海传播到热带各地。它喜高温、光照充足，耐旱但不耐寒，适宜在排水良好的酸性沙壤土生长。果实成熟期因产区而异。鲜食前常用盐水浸泡，以抑制菠萝蛋白酶；果肉可制罐头、果汁、果干，叶纤维可织布。中国广东、海南、台湾等地是主产区，果实糖度在完熟前达到高峰，需适时采收。",
