    description: "百香果是西番莲科多年生草质藤本，茎细长，叶腋生出卷须，能缠绕棚架攀援。叶片掌状三裂，边缘有锯齿，叶面光滑。花单生，花形奇特，花瓣白色，副花冠呈紫蓝色丝状，中央有雌雄蕊。果实为浆果，圆形或椭圆形，成熟时紫红或黄色，果皮硬，果肉橙黄，含多数黑色种子。\n\n百香果原产南美洲巴西、阿根廷一带，后传入澳大利亚、夏威夷和东南亚。它喜温暖、光照充足，不耐寒，适宜在疏松肥沃、排水良好的土壤生长。果实成熟后会自然脱落，可拣拾收集。果肉香气浓郁，多制果汁、果酱、甜点，也可连籽鲜食；果皮可提取果胶。中国广西、福建、云南等地栽培较多，果汁常与蜂蜜、柠檬搭配饮用。",
