    description: "胡椒是胡椒科多年生常绿藤本，茎长可达数米，茎节膨大，节上有气生根，能攀附支撑物。叶片心形或卵形，革质，互生。花小，无花瓣，穗状花序。果实为浆果，球形，未成熟时绿色，成熟后红色，干后变黑，即黑胡椒。\n\n胡椒原产印度西南部马拉巴尔海岸，栽培历史超过两千年，曾是重要的贸易香料。它喜高温高湿、半阴环境，适宜在排水良好的酸性土壤生长，常搭架栽培。果实成熟度不同可制成不同产品：未熟果晒干为黑胡椒，成熟果去皮为白胡椒，青果冷冻或盐渍为青胡椒。中国海南、云南有栽培。胡椒耐贮运，整粒可保存较久，但磨碎后香气容易散失，现磨胡椒风味更佳。",
