    description: "肉桂是樟科常绿乔木，株高 10–15 m，树皮灰褐色，厚而有芳香，剥皮后需压板定型。叶片长椭圆形，革质，互生，叶面深绿有光泽。花小，黄绿色，圆锥花序。果实为浆果，椭圆形，成熟时紫黑。树皮剥下后卷成筒状，晒干即桂皮。\n\n肉桂原产中国南方、越南和印度尼西亚，中国栽培历史悠久。它喜温暖湿润、光照充足，适宜在酸性红壤生长。树龄较大时树皮更厚、香气更浓。桂皮可作炖肉、卤味、五香粉的香料，也可提取桂皮油；桂枝、桂皮入药。中国广西、广东、福建是主要产区。肉桂喜温暖，幼树期需遮阴保湿，桂皮以皮厚、油性足者为佳，除调味外也常磨成肉桂粉。",
    habitat: "亚热带山地与丘陵，喜温暖湿润和酸性土壤",
    distribution: "原产中国南方、越南与印度尼西亚，中国广西、广东、福建栽培",
