    taxonomy: { phylum: "被子植物门", class: "双子叶植物纲", order: "桃金娘目", family: "桃金娘科", genus: "蒲桃属" },
    summary: "丁子香是桃金娘科常绿乔木，干燥花蕾即丁香，香气辛烈，是糕点、卤味和咖喱常用香料，也可提取丁香油。",
    description: "丁子香是桃金娘科常绿乔木，株高 10–20 m，树冠圆锥形，叶片长椭圆形，革质，对生。花为聚伞花序，花蕾淡绿转粉红，成熟时采摘，采收后需及时烘干，颜色转为深褐。干燥花蕾形似小钉，故称丁香，香气浓郁。果实为浆果，成熟时紫红。\n\n丁子香原产印度尼西亚马鲁古群岛，是著名的“香料群岛”特产，曾由荷兰垄断贸易。它喜高温高湿、光照充足，适宜在排水良好的火山土生长。花蕾在开放前采收，晒干后即为丁香。丁香可作糕点、卤味、咖喱和烟草香料，也可提取丁香油；丁香酚有麻醉镇痛作用。中国海南、云南有引种。丁香以花蕾完整、香气浓烈者为佳，丁子香树寿命可达百年。",
    habitat: "热带海岛与湿润丘陵，喜高温高湿",
