    description: "漆树是漆树科落叶乔木，株高 10–15 m，树皮灰白色，有纵向裂纹。奇数羽状复叶，小叶 7–15 枚，卵形，边缘全缘。花小，黄绿色，圆锥花序。果实为核果，扁圆形，成熟时黄褐色。树皮受伤后会分泌汁液，割开后渗出乳白色汁液，即生漆。\n\n漆树原产中国，栽培和利用历史超过七千年，河姆渡遗址曾出土漆器。它喜光、耐寒耐旱，适宜在土层深厚的山地生长。生漆是天然涂料，耐腐、耐磨、耐热，广泛用于漆器、家具和船舶；漆籽可榨油，木材可制器具。生漆接触皮肤可能引起过敏，割漆和涂刷需做好防护。中国陕西、湖北、四川等地是主产区。漆树喜光，幼树期稍耐阴。",
