    description: "乌桕是大戟科落叶乔木，株高 10–15 m，树皮灰褐色，树冠圆整，枝条细长，叶片菱状卵形，先端尾尖，秋季变为鲜红或橙红。花小，黄绿色，穗状花序。果实为蒴果，球形，成熟时黑褐色，开裂后露出被白色蜡质的种子。\n\n乌桕原产中国和日本，栽培历史悠久。它喜光、耐湿耐瘠，常生于溪边、田埂和山地。种子外面的白色蜡质可制蜡烛、肥皂，种仁可榨油制油漆，木材可制器具；叶和根皮可入药。秋季叶色红艳，是优良的观叶树种。中国长江流域及以南地区广泛分布，浙江、江西、湖北等地较多，乌桕耐水湿，也耐轻度盐碱，种子采收后需脱蜡处理，秋叶观赏期可达数周。",
