    description: "剑麻是龙舌兰科多年生草本，茎短缩，叶片剑形，长可达 1–1.5 m，肉质坚硬，顶端有尖刺，边缘无刺或疏生小刺，呈莲座状排列。花序高大，可达数米，花黄绿色。植株生长 6–8 年后抽薹开花，果实为蒴果，内含多数种子，但栽培种多不结实。\n\n剑麻原产墨西哥尤卡坦半岛，19 世纪起在巴西、坦桑尼亚和中国南方大规模栽培。它喜高温、光照充足，耐旱耐瘠，适宜在排水良好的沙质土生长，忌积水。叶片割下后经刮麻、清洗、晾晒可得剑麻纤维，纤维强韧、耐海水腐蚀，用于制绳索、渔网、地毯和麻袋。中国广东、广西、海南、福建等地有栽培，剑麻纤维也可制抛光轮和特种纸。",
