    description: "薏苡为禾本科薏苡属一年生草本，株高 1–1.5 米，茎秆粗壮直立，基部节上生根。叶片长披针形，宽大，中脉明显。总状花序自叶腋抽出，雌小穗包裹在骨质总苞内，雄小穗位于花序上部；总苞卵形，长 8–12 毫米，成熟时坚硬光滑，呈灰白、蓝紫或黑褐色，形如念珠，花期 7–9 月。\n\n薏苡原产亚洲热带地区，中国栽培历史可追溯至新石器时代，长江流域及以南各地广布。去壳后的种仁即薏米，富含淀粉与蛋白质，可煮粥、酿酒，中医认为其能健脾利湿、除痹止泻。坚硬的总苞在民间被串成念珠，故有“菩提子”之称。栽培喜温暖湿润、阳光充足，多直播或育苗移栽，需注意防治黑穗病；成熟期不一致，常分次采收。",
