    description: "甜叶菊为菊科甜叶菊属多年生草本，株高 0.6–1 米，茎直立，多分枝，密被短毛。叶对生，倒卵形至披针形，边缘有粗锯齿，揉碎后有清甜香气。头状花序小，白色，排成伞房状，花期 7–9 月；瘦果细小，具冠毛。\n\n甜叶菊原产南美洲巴拉圭与巴西交界的高地，当地原住民早有以叶片增甜饮料的传统。其叶片含甜菊糖苷（主要包括甜菊苷与莱鲍迪苷 A），甜度约为蔗糖的 200–300 倍，热量极低，提取物广泛用于无糖饮料、烘焙与餐桌甜味剂。栽培喜温暖湿润、日照充足，适宜疏松肥沃的土壤，不耐严寒，多用扦插或育苗移栽，一年可多次采叶。中国自 20 世纪 70 年代引种，现为世界主要种植与加工国之一。",
