    description: "留兰香为唇形科薄荷属多年生草本，具匍匐根状茎，株高 30–100 厘米，茎四棱，光滑或近光滑。叶对生，卵状披针形，长 3–7 厘米，边缘有尖锐锯齿，表面皱缩、深绿色，揉碎后散发清甜香气。轮伞花序密集组成顶生穗状花序，花小，淡紫或白色，花期 7–9 月；小坚果褐色。\n\n留兰香原产欧洲与西亚，是薄荷属中香味最清甜的一种，主要香气成分为香芹酮，而薄荷脑含量很低，因此没有普通薄荷的清凉刺激感。它广泛用于口香糖、牙膏、糖果与饮料的调味，也是英式料理中搭配羊肉的经典香草。栽培喜阳光充足、湿润肥沃的土壤，靠根状茎迅速蔓延，地栽需设根障以防泛滥；可多次刈割采叶，鲜用或阴干。",
