    description: "小茴香为伞形科茴香属多年生草本（栽培上常作一二年生），株高 1–2 米，茎直立，表面有纵纹。叶片羽状细裂，裂片丝状，形如羽毛，蓝绿色。复伞形花序顶生，花小，黄色，花期 5–7 月；双悬果长圆形，长 4–6 毫米，有纵棱，成熟后香气浓郁，即“小茴香”。\n\n小茴香原产地中海沿岸与西亚，自古为重要香料，中国北方广为栽培。其果实含茴香脑、茴香酮等挥发油，是五香粉、咖喱与卤味的核心香料，也是中医“温阳散寒、理气止痛”的常用药。球茎型品种（佛罗伦萨茴香）的肥厚叶鞘可作蔬菜。栽培喜凉爽、阳光充足，适宜疏松肥沃、排水良好的土壤，播种繁殖，忌连作与积水；果实转黄时割取全株，晒干脱粒。",
