    description: "油莎豆为莎草科莎草属多年生草本，株高 30–80 厘米，具细长根状茎与地下块茎。茎三棱形，叶线形，基生。块茎卵形至长圆形，长 1–2 厘米，成熟时褐色，表面有横纹，形似小荸荠。花序为伞形聚伞花序，花小，黄褐色，花期 6–8 月。\n\n油莎豆原产地中海沿岸与非洲北部，古埃及人已有食用记载。块茎含淀粉、糖与油脂（含油量约 20–30%），可生食、煮食、榨油、酿酒或磨粉做饮料，风味介于坚果与椰奶之间，被称为“地下核桃”。栽培喜温暖、阳光充足与疏松沙壤土，靠块茎繁殖，生长期 4–5 个月。它繁殖力极强，遗漏的小块茎次年即萌发，在部分地区的农田中被视为难除杂草。",
