    description: "龙爪稷为禾本科穇属一年生草本，株高 0.5–1.2 米，茎秆粗壮，基部常分枝。叶片线状披针形，宽 0.5–1 厘米。穗状花序数枚呈指状排列于茎顶，形如龙爪或握拳，小穗密生，种子球形，直径 1–2 毫米，红褐或深褐色，成熟后包裹在颖壳中，花期 7–9 月。\n\n龙爪稷原产非洲东部高原，后传入印度与南亚，是当地干旱地区的主粮之一，中国南方部分地区也有种植。它极耐旱、耐瘠薄，生长期仅 3–4 个月，可在雨养条件下稳产。种子可煮粥、磨粉做饼，富含钙、铁与膳食纤维，不含麸质，近年作为健康杂粮受到关注；也可酿酒、作饲料。栽培以直播为主，需注意轮作以防病害。",
