    description: "食用大黄为蓼科大黄属多年生草本，具粗壮的根状茎，株高 0.8–1.5 米。叶片大型，宽卵形至心形，直径可达 60 厘米，叶柄肥厚、呈红色或绿色，长 30–60 厘米，是主要食用部分。花葶高耸，圆锥花序大型，花小，黄绿色，花期 5–6 月；瘦果具三棱。\n\n食用大黄原产西伯利亚与东亚，18 世纪起在欧洲广泛栽培，是温带地区春季最早上市的“水果”之一（植物学上是蔬菜）。叶柄酸味来自苹果酸与草酸，需加糖烹煮，常做馅饼、果酱与糖煮大黄。叶片草酸含量高，不可食用。栽培喜冷凉、阳光充足与深厚肥沃的土壤，以根状茎分株或播种繁殖，需培土软化叶柄以获柔嫩品质，冬季寒冷地区地上部枯萎越冬。",
