    description: "甘露子为唇形科水苏属多年生草本，株高 30–60 厘米，茎方形，被短毛。叶对生，卵形，边缘有锯齿。地下具匍匐茎，先端膨大成螺旋状块茎，长 2–4 厘米，白色至淡黄色，节间缢缩如串珠。轮伞花序腋生，花冠淡紫或白色，唇形，花期 7–8 月；小坚果黑褐色。\n\n甘露子原产中国华北与西北，各地多有栽培，块茎形似宝塔或蚕蛹，故有“宝塔菜”“草石蚕”之称。块茎质脆味甜，可鲜食、炒食，更多用于腌渍酱菜，是北方酱菜中的经典品种；全草入药，有祛风利湿、活血散瘀之效。栽培喜温暖湿润、疏松肥沃的沙壤土，以块茎繁殖，秋季地上部枯萎后掘取块茎，留存小块茎作种。它适应性强，房前屋后零星种植即可丰收。",
    habitat: "温暖湿润的菜园、田边与房前屋后，喜疏松沙壤土",
