    description: "苤蓝为十字花科芸薹属二年生草本，是甘蓝的一个变种，株高 30–60 厘米。茎基部膨大形成扁球形肉质茎，直径 5–10 厘米，皮色浅绿或紫红，肉质白色脆嫩。叶互生，长椭圆形，蓝绿色，有长叶柄，着生于球茎上部。第二年抽薹开花，花黄色，总状花序；长角果，种子黑褐色。\n\n苤蓝原产欧洲地中海沿岸，16 世纪起在欧洲广泛栽培，中国南北各地亦有种植。膨大的球茎可生食、切丝凉拌、炒食或腌渍，口感介于萝卜与茎蓝之间，脆甜多汁；嫩叶也可作蔬菜。它富含维生素 C 与膳食纤维，热量低。栽培喜冷凉、阳光充足与疏松肥沃的土壤，多为春秋两季育苗移栽，生长期 60–80 天，球茎充分膨大但未木质化时采收，过晚则纤维增多。",
