    description: "根芹为伞形科芹属二年生草本，是芹菜的变种，株高 30–60 厘米。肉质根膨大成扁球形，直径 8–15 厘米，表面粗糙、灰褐色，内部白色细密，具浓郁芹菜香气。叶为二回羽状复叶，小叶深裂，深绿色，叶柄较细。第二年抽薹，复伞形花序，花小，白色；双悬果细小。\n\n根芹原产地中海沿岸与欧洲南部，是欧洲传统根菜，中国近年有引种。膨大的根部可煮、烤、炖、做浓汤或切丝凉拌，风味比芹菜温和、质地似土豆，是法式“芹菜根沙拉”与炖菜的基础食材；叶片也可作香草。它富含膳食纤维与维生素 K，热量低。栽培喜冷凉、湿润与深厚疏松的土壤，需较长生长期（约 4–5 个月），育苗移栽，生长期间需充足水分，否则根部易空心、纤维化。",
