    description: "蛇瓜为葫芦科栝楼属一年生攀援草本，茎细长，卷须分叉，攀援力强。叶掌状分裂，边缘有齿。花单性，雌雄同株，花冠白色，边缘丝状流苏，傍晚开放，次日凋萎。果实细长圆柱形，长 1–2 米，常扭曲如蛇，幼果绿色带白色条纹，成熟后转橙红，果肉海绵状；种子扁椭圆形。\n\n蛇瓜原产印度与东南亚，中国南方有栽培。嫩果可切片炒食、做汤，口感近似丝瓜但略带清苦，需煮透；成熟果实不可食，但老熟后的纤维可作洗刷用具。栽培喜高温、阳光充足与肥沃土壤，需搭高架供其垂挂，生长期 3–4 个月，果实趁嫩采收，过老则纤维化。它的花在傍晚开放，白色流苏状花冠颇具观赏性，也常被种在棚架上作绿荫。",
