    description: "芝麻菜为十字花科芝麻菜属一年生草本，株高 20–80 厘米，茎直立，疏生糙毛。基生叶羽状深裂，裂片圆钝，形似蒲公英叶，揉碎后有芝麻与胡椒混合的辛香；茎生叶较小，披针形。总状花序顶生，花白色或淡黄，花瓣带紫色脉纹，花期 4–6 月；长角果直立，种子褐色。\n\n芝麻菜原产地中海沿岸与西亚，古罗马人已栽培食用，是披萨与意面沙拉的经典配料。嫩叶生食有芝麻香与轻微辛辣，老叶则苦味加重，可炒食或做青酱。栽培喜冷凉、阳光充足，适宜疏松肥沃土壤，春秋播种，播后 30–40 天可陆续采叶；高温易抽薹、风味变苦。它也是“芝麻菜沙拉”与“火箭菜”名称的由来。",
    habitat: "地中海气候的干燥坡地、田边与菜园，喜光、耐旱、喜冷凉",
    distribution: "原产地中海沿岸与西亚，意大利等地广泛栽培，中国各地有引种",
