      { label: "光照", value: "喜光，生长期需充足日照" },
      { label: "水分", value: "耐旱，忌积水" },
      { label: "土壤", value: "不择土壤，以疏松的沙质壤土为佳" },
      { label: "主要用途", value: "杂粮（苦荞茶、苦荞面）、药用与饲料" }
