    description: "青稞为一年生草本，高 60–100 厘米，茎直立、丛生。叶片线形，长 10–20 厘米，叶鞘抱茎。穗状花序顶生，小穗多花，芒长，成熟时穗轴易折断；颖果裸露，不与稃壳粘连，成熟时黄褐色至紫黑色，千粒重较高。\n\n青稞是大麦的裸粒变种，主要分布于中国西藏、青海、四川西部、云南西北部与甘肃南部，生于海拔 3000–4500 米的高原，耐寒、耐旱、耐瘠薄，是青藏高原唯一能大面积种植的粮食作物。青稞可磨成糌粑，是藏族传统主食；也可酿制青稞酒、制作青稞面条。它富含 β-葡聚糖与膳食纤维，近年来被开发为健康食品。青稞秸秆是高原牲畜的重要越冬饲料。",
