    description: "饭豆为一年生草本，高 30–100 厘米，茎直立或半蔓生，被短柔毛。叶为三出复叶，小叶卵形至披针形，长 5–10 厘米。总状花序腋生，花黄色，龙骨瓣弯曲；荚果细长、圆柱形，长 6–10 厘米，成熟时黄褐色，内含 6–10 粒种子，种子长圆形，红色、黄色或黑色。\n\n饭豆原产南亚与东南亚，在中国南方栽培历史悠久，分布于广东、广西、云南、贵州、福建等地，耐旱、耐瘠薄、生育期短。它的籽粒富含蛋白质与淀粉，可煮粥、做豆沙或与米饭同煮，是南方山区重要的杂粮；茎叶可作饲料，也可作绿肥。饭豆在东南亚常与玉米、木薯间作，是热带地区重要的固氮作物。",
