    description: "木豆为多年生灌木状草本，高 1–3 米，茎直立、木质化，多分枝，被短柔毛。叶为三出复叶，小叶披针形至椭圆形，长 5–10 厘米。总状花序腋生，花黄色或带紫红色斑纹；荚果扁平、长圆形，长 4–7 厘米，成熟时褐色，内含 2–5 粒种子，种子圆形，褐色或灰白色。\n\n木豆原产印度，广泛栽培于热带与亚热带地区，在中国广东、广西、云南、海南、福建等地有种植，耐旱、耐瘠薄、固氮能力强。它的籽粒富含蛋白质，可煮食、做豆泥或磨粉，是印度与非洲重要的植物蛋白来源；茎叶可作饲料与绿肥，枝条可作薪柴。木豆还是紫胶虫的优良寄主，可生产紫胶。",
