    summary: "豆科兵豆属一年生草本，荚果扁小、籽粒扁圆如透镜，耐旱耐瘠，是地中海与南亚地区常见的食用豆类。",
    description: "兵豆为一年生草本，高 20–60 厘米，茎直立或分枝，被细柔毛。叶为羽状复叶，小叶 3–7 对，长椭圆形，叶轴末端具卷须。花小，白色至淡蓝色，单生或 2–3 朵生于叶腋；荚果扁矩形，长 1–2 厘米，内含 1–2 粒种子，种子扁圆、形似透镜，颜色有黄、绿、红、黑等。\n\n兵豆原产中东与地中海地区，是世界上最古老的栽培作物之一，在中国西北与华北有少量种植，耐旱、耐瘠薄、生长期短。它的籽粒富含蛋白质与铁，可煮汤、做豆泥或发芽食用，是南亚与中东饮食中的主食豆类；茎叶可作饲料。兵豆的固氮能力可改善土壤，常与小麦轮作。在印度，兵豆常被煮成浓汤（dal），是日常饮食的主角。",
