    taxonomy: { phylum: "被子植物门", class: "木兰纲", order: "豆目", family: "豆科", genus: "山黧豆属" },
    summary: "豆科山黧豆属一年生草本，耐旱耐瘠、籽粒蛋白含量高，但含神经毒素 ODAP，长期大量食用可致山黧豆中毒。",
    description: "山黧豆为一年生草本，高 30–100 厘米，茎直立或蔓生，具翅状棱。叶为羽状复叶，小叶 1–2 对，线状披针形，叶轴末端具卷须。花单生叶腋，白色、蓝色或紫红色；荚果扁长圆形，长 3–5 厘米，内含 2–4 粒种子，种子楔形，灰白色至褐色。\n\n山黧豆原产地中海与西亚，在中国西北、华北有栽培，耐旱、耐瘠薄、抗逆性强，是干旱地区重要的救荒作物。它的籽粒蛋白质含量高，但含有神经毒素 β-N-草酰氨基丙氨酸（ODAP），长期大量单一食用会导致山黧豆中毒（下肢痉挛性瘫痪）。因此食用前需充分浸泡、煮熟，并控制摄入量，不可长期以它为主食。山黧豆也可作饲料与绿肥。",
    habitat: "温带干旱与半干旱地区，耐旱、耐瘠薄、抗逆性强",
