    description: "紫花苜蓿为多年生草本，高 30–100 厘米，主根发达、可深入土中数米，茎直立或斜升，多分枝。叶为三出复叶，小叶倒卵形至长圆形，边缘具细齿，托叶披针形。总状花序腋生，花冠紫色至淡紫色，长 1–1.5 厘米；荚果螺旋状卷曲，内含数粒肾形种子。\n\n紫花苜蓿原产西亚与中亚，是世界上最古老的栽培牧草之一，在中国西北、华北、东北广泛种植，耐旱、耐寒、耐盐碱，固氮能力强。它的茎叶富含蛋白质与维生素，是奶牛、肉牛与羊的优质饲料，被誉为“牧草之王”；也可作绿肥、水土保持植物与蜜源。紫花苜蓿根系深长，能改良土壤结构；其嫩芽在西方常作沙拉食用。",
